<?php
function reportUrl(string $route,array $filters,array $extra=[]):string {return url($route).'&'.http_build_query(array_merge($filters,$extra));}
function reportMoney(mixed $v):string {return $v===null?'Unavailable':money($v);}
function reportExport(string $kind,array $filters):void { ?><div class="report-export"><a class="button button-small" href="<?= e(reportUrl('/reports/export',$filters,['dataset'=>$kind,'format'=>'csv'])) ?>">CSV</a><a class="button button-small" href="<?= e(reportUrl('/reports/export',$filters,['dataset'=>$kind,'format'=>'xlsx'])) ?>">Excel</a></div><?php }
function reportChart(array $rows,string $name,string $value,string $title,bool $currency=true):void {
 if(!$rows){ ?><p class="empty-state">No matching transactions in this period.</p><?php return; }
 $max=max(array_map(fn($r)=>abs((float)($r[$value]??0)),$rows));if($max<=0){ ?><p class="empty-state">No recorded amounts for this period.</p><?php return; }
 $width=660;$height=250;$left=12;$right=12;$bottom=55;$top=28;$available=$width-$left-$right;$step=$available/count($rows);$bar=max(1,$step*.65);$ticks=max(1,(int)ceil(count($rows)/7)); ?>
 <div class="report-chart"><svg viewBox="0 0 <?= $width ?> <?= $height ?>" role="img" aria-label="<?= e($title) ?>"><title><?= e($title) ?></title><line x1="12" y1="195" x2="648" y2="195" stroke="#dce3d5"/><?php foreach($rows as $i=>$row): $v=(float)($row[$value]??0);$h=abs($v)/$max*($height-$bottom-$top);$x=$left+$i*$step+($step-$bar)/2;$label=(string)$row[$name]; ?><g><title><?= e($label.' · '.($currency?money($row[$value]??0):quantity($row[$value]??0))) ?></title><rect x="<?= $x ?>" y="<?= $height-$bottom-$h ?>" width="<?= $bar ?>" height="<?= max(0,$h) ?>" rx="2" fill="<?= $v<0?'#b57356':'#5d7b54' ?>"/><?php if($i%$ticks===0): ?><text x="<?= $x+$bar/2 ?>" y="213" text-anchor="middle" fill="#67745f" font-size="11"><?= e(mb_strimwidth($label,0,16,'…')) ?></text><?php endif; ?></g><?php endforeach; ?><text x="12" y="16" fill="#67745f" font-size="11">Max <?= e($currency?money($max):quantity($max)) ?></text></svg></div>
<?php }
function reportTable(string $kind,array $rows,array $user):void {
 $columns=App\Services\ReportExportService::columns($kind);$visible=match($kind){'products'=>['name','sku','quantity','revenue','cogs','profit','margin','missing_cost_lines'],'stock'=>['name','sku','category','quantity','stock_value','sold_quantity','stock_status'],'invoices','invoice_exceptions'=>['invoice_number','created_at','customer','total','taxable','balance_due','status'],'movements'=>['id','name','movement_type','quantity_delta','reason','entry_date','reference_id'],'services'=>['invoice_number','created_at','description','revenue'],'exceptions'=>['invoice_number','id','name','unit_cost','reason'],default=>array_keys($columns)};
 ?>
 <div class="report-table-wrap"><table class="report-table"><thead><tr><?php foreach($visible as $field): ?><th><?= e($columns[$field][0]) ?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $row): ?><tr><?php foreach($visible as $field): $v=$row[$field]??null; ?><td data-label="<?= e($columns[$field][0]) ?>"><?php if($field==='invoice_number' && can($user,'sales.view') && (in_array($kind,['invoices','invoice_exceptions','exceptions'],true))): ?><a href="<?= e(url('/sales/invoice')) ?>&amp;id=<?= (int)($row['sale_id']??$row['id']) ?>"><?= e((string)$v) ?></a><?php elseif($kind==='movements' && $field==='id' && can($user,'inventory.movements')): ?><a href="<?= e(url('/inventory/movement')) ?>&amp;id=<?= (int)$v ?>">#<?= (int)$v ?></a><?php elseif($v===null): ?><span class="report-unavailable"><?= in_array($field,['cogs','profit','revenue','stock_value'],true)?'Unavailable':'—' ?></span><?php elseif(in_array($field,['quantity','quantity_delta','sold_quantity'],true)): ?><?= quantity($v) ?><?php elseif(in_array($field,['total','taxable','revenue','cogs','profit','stock_value','balance_due','unit_cost'],true)): ?><?= money($v) ?><?php elseif($field==='margin'): ?><?= e((string)$v) ?>%<?php else: ?><?= e((string)$v) ?><?php endif; ?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows): ?><p class="empty-state">No records match this report.</p><?php endif; ?>
<?php }
function reportPagination(array $listing,array $filters,string $route):void { ?><nav class="pagination report-pagination" aria-label="Report pages"><span><?= (int)$listing['total'] ?> records · Page <?= (int)$listing['page'] ?> / <?= (int)$listing['pages'] ?></span><?php foreach(['Previous'=>$listing['page']-1,'Next'=>$listing['page']+1] as $label=>$page): if($page<1 || $page>$listing['pages'])continue; ?><a class="button button-small" href="<?= e(reportUrl($route,$filters,['page'=>$page])) ?>"><?= e($label) ?></a><?php endforeach; ?></nav><?php }
